"""Lot 3 : Tapoa, Djôrô, Nakambé, Goulmou, Nazinon."""
from tales_kit import art, choice, gloss, it, quiz, scene, tale

# ------------------------------------------------------------------ Tapoa
tale(49, "le-chasseur-et-l-elephant-reconnaissant", type="conte", region="tapoa", place="Diapaga",
     coords=(12.07, 1.79), people="Gourmantché", language="gulmancema", duration=5, age=6,
     tags=["animaux", "gratitude", "parc W", "brousse"], featured=True, cover=2,
     fr=("Le chasseur et l'éléphant reconnaissant", "Près du parc du W",
         "Un chasseur de Diapaga retire une épine du pied d'un éléphant. Des années plus tard, perdu dans la brousse, c'est l'éléphant qui le ramène chez lui.",
         "Un bienfait n'est jamais perdu : la brousse se souvient."),
     en=("The Hunter and the Grateful Elephant", "Near the W park",
         "A hunter from Diapaga pulls a thorn from an elephant's foot. Years later, lost in the bush, it is the elephant who brings him home.",
         "A kindness is never lost: the bush remembers."),
     scenes=[
         scene(art("day", "savanna", it("sun", 82, 300), it("elephant", 56, s=0.9), it("hunter", 26), it("acacia", 86, 26)),
               "Près de Diapaga, aux portes du grand parc du W, vivait Yemboado, un chasseur gourmantché. Un jour, il entendit un barrissement de douleur : un jeune éléphant boitait, une longue épine plantée dans le pied.",
               "Near Diapaga, at the edge of the great W park, lived Yemboado, a Gourmantché hunter. One day he heard a trumpet of pain: a young elephant was limping, a long thorn stuck in its foot."),
         scene(art("day", "savanna", it("elephant", 54, s=0.9), it("hunter", 36), it("spear", 18), it("bush", 80, 10)),
               "Ses compagnons voulaient profiter de l'occasion pour le chasser. Yemboado posa sa lance.",
               "His companions wanted to take the chance to hunt it. Yemboado laid down his spear.",
               choice(("Que va faire Yemboado ?", "What will Yemboado do?"),
                      [("Retirer l'épine", "Pull out the thorn"), ("Chasser l'éléphant", "Hunt the elephant")], 0,
                      ("Doucement, il retira l'épine. L'éléphant le regarda longtemps, puis s'en alla.", "Gently he pulled out the thorn. The elephant looked at him for a long time, then left."))),
         scene(art("night", "forest", it("moon", 76, 300), it("hunter", 40), it("forest-edge", 70), it("owl", 84, 110)),
               "Des années passèrent. Un soir d'orage, Yemboado se perdit au fond de la brousse. La nuit tombait, les hyènes riaient au loin et il ne retrouvait plus aucun sentier.",
               "Years passed. One stormy evening, Yemboado got lost deep in the bush. Night was falling, hyenas laughed in the distance and he could no longer find any path."),
         scene(art("dawn", "savanna", it("sun", 16, 240), it("elephant", 52, s=1), it("hunter", 34), it("hut", 84, 26)),
               "Un grand éléphant sortit des arbres et s'arrêta devant lui. Yemboado reconnut la cicatrice sur son pied. L'éléphant marcha devant lui toute la nuit, jusqu'aux premières cases de Diapaga. Depuis, sa famille ne chasse plus jamais l'éléphant.",
               "A great elephant came out of the trees and stopped in front of him. Yemboado recognised the scar on its foot. The elephant walked ahead of him all night, as far as the first huts of Diapaga. Since then, his family has never hunted elephants again."),
     ],
     quizzes=[
         quiz(("Qu'avait l'éléphant dans le pied ?", "What was in the elephant's foot?"),
              [("Une épine", "A thorn"), ("Une flèche", "An arrow"), ("Une pierre", "A stone")], 0),
         quiz(("Comment le chasseur a-t-il retrouvé son chemin ?", "How did the hunter find his way?"),
              [("L'éléphant l'a guidé", "The elephant guided him"), ("Avec une carte", "With a map"), ("Grâce au soleil", "Thanks to the sun")], 0),
     ],
     glossary=[gloss("parc du W", "fr", "Grand parc naturel partagé avec le Niger et le Bénin, nommé d'après la forme du fleuve Niger ; patrimoine mondial de l'UNESCO.", "A large nature park shared with Niger and Benin, named after the shape of the Niger river; a UNESCO World Heritage site.")],
     source=("Conte de l'animal reconnaissant (l'épine retirée), répandu en Afrique comme en Europe. Version écrite pour KIBARE, située en pays gourmantché, près du parc du W.",
             "A tale of the grateful animal (the thorn removed), widespread in Africa and Europe. Version written for KIBARE, set in Gourmantché country near the W park."))

tale(50, "pourquoi-les-pintades-de-kantchari-crient-a-l-aube", type="conte", region="tapoa", place="Kantchari",
     coords=(12.48, 1.52), people="Gourmantché", language="gulmancema", duration=3, age=4,
     tags=["animaux", "pourquoi", "matin", "vigilance"], cover=1,
     fr=("Pourquoi les pintades crient à l'aube", "Les sentinelles de Kantchari",
         "Le chacal surprend les animaux endormis. Les pintades décident de veiller pour tous, et depuis, elles réveillent la brousse chaque matin.",
         "Celui qui veille pour les autres mérite la confiance de tous."),
     en=("Why Guinea Fowl Cry at Dawn", "The sentinels of Kantchari",
         "The jackal takes the sleeping animals by surprise. The guinea fowl decide to keep watch for everyone, and ever since they wake the bush every morning.",
         "Whoever keeps watch for others deserves everyone's trust."),
     scenes=[
         scene(art("night", "savanna", it("moon", 76, 300), it("guinea-fowl", 30, s=1.2), it("hare", 50), it("dog", 74, c="#C9822B", flip=True)),
               "Autrefois, autour de Kantchari, tous les animaux dormaient jusqu'au grand soleil. Le chacal en profitait : chaque nuit, il volait les œufs et les petits des dormeurs.",
               "Long ago, around Kantchari, all the animals slept until the sun was high. The jackal took advantage: every night he stole the eggs and young of the sleepers."),
         scene(art("dawn", "savanna", it("guinea-fowl", 34, s=1.3), it("guinea-fowl", 46, s=1.1), it("partridge", 60), it("tortoise", 76)),
               "Les animaux tinrent conseil. Qui voudrait se lever avant tout le monde pour donner l'alerte ? Personne n'osait. Alors la mère pintade dit : « Nous, les pintades, nous veillerons. »",
               "The animals held a council. Who would get up before everyone to sound the alarm? Nobody dared. Then Mother Guinea Fowl said: \"We guinea fowl will keep watch.\"",
               choice(("Est-ce une bonne idée ?", "Is it a good idea?"),
                      [("Oui, veiller protège tout le monde", "Yes, keeping watch protects everyone"), ("Non, c'est trop fatigant", "No, it's too tiring")], 0,
                      ("La nuit suivante, les pintades se relayèrent…", "The next night, the guinea fowl took turns…"))),
         scene(art("dawn", "savanna", it("sun", 16, 230), it("guinea-fowl", 40, s=1.3), it("dog", 70, c="#C9822B"), it("bush", 84, 10)),
               "Au petit matin, le chacal s'approcha. Aussitôt les pintades crièrent toutes ensemble : « Ka-ka-ka-ka ! » Toute la brousse se réveilla, et le chacal s'enfuit, la queue entre les pattes.",
               "At daybreak the jackal crept closer. At once the guinea fowl all cried out together: \"Ka-ka-ka-ka!\" The whole bush woke up, and the jackal ran off with his tail between his legs."),
         scene(art("day", "village", it("sun", 84, 300), it("guinea-fowl", 30, s=1.2), it("guinea-fowl", 42), it("woman", 64), it("hut", 82, 26)),
               "Depuis ce jour, à Kantchari comme ailleurs, les pintades crient dès l'aube. Les hommes les élèvent près des cases, car elles sont les meilleures sentinelles de la cour.",
               "Since that day, in Kantchari and elsewhere, guinea fowl cry at dawn. People raise them near their huts, for they are the best sentinels of the yard."),
     ],
     quizzes=[
         quiz(("Qui volait les œufs la nuit ?", "Who stole the eggs at night?"),
              [("Le chacal", "The jackal"), ("Le lièvre", "The hare"), ("La tortue", "The tortoise")], 0),
         quiz(("Que font les pintades à l'aube ?", "What do guinea fowl do at dawn?"),
              [("Elles crient pour réveiller", "They cry to wake everyone"), ("Elles dorment", "They sleep"), ("Elles chantent une chanson", "They sing a song")], 0),
     ],
     glossary=[gloss("sentinelle", "fr", "Celui ou celle qui monte la garde pour prévenir d'un danger.", "Someone who stands guard to warn of danger.")],
     source=("Conte étiologique écrit pour KIBARE dans l'esprit des contes d'animaux gourmantché ; la pintade est l'oiseau des cours de l'Est du Burkina.",
             "A \"why\" tale written for KIBARE in the spirit of Gourmantché animal tales; the guinea fowl is the yard bird of eastern Burkina."))

# ------------------------------------------------------------------ Djôrô
tale(51, "le-bagr-la-parole-des-origines", type="legende", region="djoro", place="Dano",
     coords=(11.15, -3.06), people="Dagara", language="dagara", duration=5, age=9,
     tags=["origines", "initiation", "parole", "savoir"], featured=True, cover=3,
     fr=("Le Bagr, la parole des origines", "Le plus long récit des Dagara",
         "Chez les Dagara, un récit sacré, le Bagr, raconte comment les hommes ont reçu le savoir. On le récite pendant des heures, sans s'arrêter, lors de l'initiation.",
         "Le savoir des ancêtres se transmet par la parole, la patience et le respect."),
     en=("The Bagr, Word of the Origins", "The Dagara's longest story",
         "Among the Dagara, a sacred story, the Bagr, tells how people received knowledge. It is recited for hours, without stopping, during initiation.",
         "The ancestors' knowledge is passed on through speech, patience and respect."),
     scenes=[
         scene(art("night", "village", it("moon", 76, 300), it("fire", 46), it("elder-sit", 30), it("child-sit", 60), it("child-sit", 70, c="#C9822B")),
               "Dans les villages dagara autour de Dano, il existe un récit si long qu'un seul homme peut le dire pendant trois heures sans s'interrompre. On l'appelle le Bagr. Il n'est pas raconté pour amuser, mais pour enseigner.",
               "In the Dagara villages around Dano, there is a story so long that a single man can recite it for three hours without stopping. It is called the Bagr. It is not told to entertain, but to teach."),
         scene(art("dusk", "forest", it("man", 30, c="#7C3109"), it("dwarf", 56), it("forest-edge", 78), it("karite", 14, 24)),
               "Le Bagr raconte qu'au commencement, les hommes souffraient de maladies et de malheurs sans les comprendre. Deux d'entre eux partirent dans la brousse, là où vivent les êtres invisibles, pour chercher le savoir.",
               "The Bagr tells that in the beginning, people suffered illnesses and misfortunes without understanding them. Two of them went into the bush, where the invisible beings live, to seek knowledge.",
               choice(("Que vont-ils chercher dans la brousse ?", "What will they seek in the bush?"),
                      [("Le savoir pour guérir et vivre", "Knowledge to heal and live"), ("De l'or", "Gold")], 0,
                      ("Ils marchèrent longtemps, guidés par les esprits…", "They walked for a long time, guided by the spirits…"))),
         scene(art("night", "forest", it("moon", 76, 300), it("dwarf", 40), it("man-talk", 60, c="#7C3109"), it("calabash", 50), it("leaf-mask", 82)),
               "Les êtres de la brousse leur enseignèrent les plantes qui soignent, les sacrifices qui apaisent et les règles qui permettent de vivre ensemble. Mais ce savoir était précieux : il ne devait être confié qu'à ceux qui sauraient le respecter.",
               "The beings of the bush taught them the plants that heal, the offerings that appease and the rules that allow people to live together. But this knowledge was precious: it was to be entrusted only to those who would respect it."),
         scene(art("day", "village", it("sun", 84, 300), it("elder", 30), it("man-up", 50, c="#7C3109"), it("child-up", 62), it("drum", 78)),
               "C'est pourquoi, chaque année, les initiés du Bagr se retirent pour écouter le récit en entier, en blanc puis en noir. Les chercheurs le considèrent comme l'un des plus longs récits oraux d'Afrique. Ici, nous n'en montrons qu'un tout petit reflet.",
               "That is why, every year, the Bagr initiates withdraw to hear the whole story, in its white and then its black form. Scholars regard it as one of Africa's longest oral narratives. Here we show only a tiny reflection of it."),
     ],
     quizzes=[
         quiz(("Combien de temps peut durer la récitation du Bagr ?", "How long can the recitation of the Bagr last?"),
              [("Environ trois heures", "About three hours"), ("Cinq minutes", "Five minutes"), ("Une semaine", "A week")], 0),
         quiz(("À quoi sert le Bagr ?", "What is the Bagr for?"),
              [("À transmettre le savoir", "To pass on knowledge"), ("À faire rire", "To make people laugh"), ("À vendre au marché", "To sell at market")], 0),
     ],
     glossary=[gloss("initiation", "fr", "Ensemble de rites par lesquels on reçoit un savoir et l'on entre dans un nouveau groupe.", "A set of rites through which one receives knowledge and enters a new group.")],
     source=("D'après les travaux d'Alexis B. Tengan sur le Bagr dagara (« The Art of Mythical Composition and Narration », « Mythical Narratives in Ritual », Peter Lang), dont le Bagr noir est décrit comme l'un des plus longs récits oraux d'Afrique. Évocation très simplifiée, sans révéler le contenu initiatique.",
             "Based on Alexis B. Tengan's work on the Dagara Bagr (\"The Art of Mythical Composition and Narration\", \"Mythical Narratives in Ritual\", Peter Lang), whose Black Bagr is described as one of Africa's longest oral narratives. A very simplified evocation that does not reveal initiatory content."))

tale(52, "le-thil-gardien-de-la-case", type="conte", region="djoro", place="Gaoua",
     coords=(10.33, -3.18), people="Lobi", language="lobiri", duration=4, age=7,
     tags=["esprits", "protection", "respect", "famille"], cover=0,
     fr=("Le thil, gardien de la case", "La statuette oubliée",
         "Un jeune Lobi de Gaoua se moque de la petite statuette que son grand-père honore. Quand le malheur frappe la famille, il comprend ce qu'elle représente.",
         "Respecter les croyances de ses aînés, c'est respecter ceux qui nous ont protégés."),
     en=("The Thil, Guardian of the Home", "The forgotten statuette",
         "A young Lobi from Gaoua mocks the little statuette his grandfather honours. When misfortune strikes the family, he understands what it stands for.",
         "Respecting your elders' beliefs means respecting those who protected us."),
     scenes=[
         scene(art("day", "village", it("sun", 82, 300), it("painted-house", 60, 30, 0.8), it("elder-sit", 30), it("child", 44), it("plank-mask", 76, 10, 0.6)),
               "À Gaoua, Sié vivait dans la grande maison de terre de sa famille. Dans un coin sombre se trouvait une petite statuette de bois. Son grand-père l'appelait le thil, l'esprit protecteur, et lui offrait chaque matin un peu de farine.",
               "In Gaoua, Sié lived in his family's big earthen house. In a dark corner stood a small wooden statuette. His grandfather called it the thil, the protective spirit, and offered it a little flour every morning."),
         scene(art("dusk", "village", it("child", 40), it("elder", 60), it("painted-house", 82, 30, 0.7)),
               "Sié riait : « Ce n'est qu'un morceau de bois ! » Un jour, il cacha la statuette au fond du grenier pour faire une farce.",
               "Sié laughed: \"It's just a piece of wood!\" One day he hid the statuette at the back of the granary as a joke.",
               choice(("Sié a-t-il eu raison ?", "Was Sié right?"),
                      [("Non, il a manqué de respect", "No, he was disrespectful"), ("Oui, c'était drôle", "Yes, it was funny")], 0,
                      ("Les jours suivants furent étranges…", "The following days were strange…"))),
         scene(art("night", "village", it("moon", 76, 300), it("snake", 40), it("child", 60), it("rain", 50, 300), it("painted-house", 80, 30, 0.7)),
               "Un serpent entra dans la cour, l'orage abîma le toit et la chèvre s'égara. Sié eut peur. Son grand-père lui dit doucement : « Le thil, c'est la mémoire de ceux qui ont veillé sur nous. On ne le cache pas. »",
               "A snake came into the yard, the storm damaged the roof and the goat wandered off. Sié was frightened. His grandfather told him gently: \"The thil is the memory of those who watched over us. We don't hide it.\""),
         scene(art("day", "village", it("sun", 84, 300), it("child-up", 40), it("elder-sit", 56), it("plank-mask", 72, 10, 0.6), it("goat", 84)),
               "Sié remit la statuette à sa place et demanda pardon. Il ne comprit pas tout, mais il apprit à respecter ce que les anciens respectent. Et le soir même, la chèvre revint seule à la maison.",
               "Sié put the statuette back in its place and asked for forgiveness. He did not understand everything, but he learned to respect what the elders respect. And that very evening, the goat came home on its own."),
     ],
     quizzes=[
         quiz(("Qu'est-ce que le thil pour la famille ?", "What is the thil to the family?"),
              [("Un esprit protecteur", "A protective spirit"), ("Un jouet", "A toy"), ("Un outil", "A tool")], 0),
         quiz(("Qu'a fait Sié à la fin ?", "What did Sié do at the end?"),
              [("Il a remis la statuette et demandé pardon", "He put the statuette back and apologised"), ("Il l'a vendue", "He sold it"), ("Il l'a cassée", "He broke it")], 0),
     ],
     glossary=[gloss("thil", "lobiri", "Chez les Lobi, esprit protecteur auquel on rend un culte à la maison (pluriel : thila).", "Among the Lobi, a protective spirit honoured in the home (plural: thila).")],
     source=("Conte écrit pour KIBARE, inspiré de la place des thila, esprits protecteurs et de leurs statuettes dans les maisons lobi de la région de Gaoua (musée de Gaoua, études ethnographiques sur les Lobi).",
             "A tale written for KIBARE, inspired by the role of the thila, protective spirits and their statuettes, in Lobi homes around Gaoua (Gaoua museum, ethnographic studies of the Lobi)."))

# ------------------------------------------------------------------ Nakambé
tale(53, "les-bissa-et-les-arachides", type="conte", region="nakambe", place="Garango",
     coords=(11.80, -0.55), people="Bissa", language="bissa", duration=4, age=6,
     tags=["parenté à plaisanterie", "arachide", "paix", "humour"], cover=2,
     fr=("Les Bissa et les arachides", "Une parenté pour rire",
         "Entre Bissa et Gourounsi, on se taquine sans jamais se fâcher : ce sont des « parents à plaisanterie ». Tout commence, dit-on, par une affaire d'arachides.",
         "Rire ensemble plutôt que se battre : c'est ainsi que les peuples se gardent en paix."),
     en=("The Bissa and the Groundnuts", "A kinship for laughing",
         "Between the Bissa and the Gurunsi, people tease each other without ever taking offence: they are \"joking relatives\". It all began, they say, with a matter of groundnuts.",
         "Laughing together rather than fighting: that is how peoples keep the peace."),
     scenes=[
         scene(art("day", "village", it("sun", 82, 300), it("woman-pound", 34, c="#E69135"), it("sack", 54), it("field", 76, 20, 0.6), it("hut", 14, 26)),
               "Les Bissa de Garango sont de grands cultivateurs d'arachides. On dit qu'ils en mangent matin, midi et soir, grillées, en pâte ou en sauce. Leurs voisins gourounsi s'en amusaient beaucoup.",
               "The Bissa of Garango are great groundnut farmers. People say they eat them morning, noon and night, roasted, as paste or in sauce. Their Gurunsi neighbours found this very amusing."),
         scene(art("dusk", "village", it("man-point", 30, c="#2F3E6B"), it("man-talk", 56, c="#7C3109", flip=True), it("sack", 44)),
               "Un jour, un Gourounsi lança à un Bissa : « Toi, tu as plus d'arachides dans le ventre que de cervelle ! » Le Bissa répliqua aussitôt : « Et toi, tu n'as même pas d'arachides pour nourrir la tienne ! » La foule retint son souffle.",
               "One day a Gurunsi called out to a Bissa: \"You've got more groundnuts in your belly than brains in your head!\" The Bissa shot back: \"And you don't even have groundnuts to feed yours!\" The crowd held its breath.",
               choice(("Que va-t-il se passer ?", "What will happen?"),
                      [("Ils vont éclater de rire", "They'll burst out laughing"), ("Ils vont se battre", "They'll fight")], 0,
                      ("Les deux hommes se regardèrent… et éclatèrent de rire.", "The two men looked at each other… and burst out laughing."))),
         scene(art("day", "village", it("sun", 16, 260), it("man-up", 30, c="#2F3E6B"), it("man-up", 46, c="#7C3109"), it("calabash", 60), it("elder", 76)),
               "Les anciens en firent une règle : entre Bissa et Gourounsi, on a le droit de se taquiner, mais on n'a pas le droit de se fâcher, ni de se faire du mal. Si l'un est en difficulté, l'autre doit l'aider.",
               "The elders made it a rule: between Bissa and Gurunsi, teasing is allowed, but getting angry or harming each other is not. If one is in trouble, the other must help."),
         scene(art("day", "village", it("sun", 84, 300), it("child-up", 30), it("child", 42, c="#C9822B"), it("sack", 56), it("woman", 72)),
               "Aujourd'hui encore, quand un Bissa rencontre un Gourounsi, les plaisanteries sur les arachides fusent. C'est la parenté à plaisanterie, une tradition burkinabè qui aide à désamorcer les conflits par le rire.",
               "To this day, when a Bissa meets a Gurunsi, groundnut jokes fly. This is the joking kinship, a Burkinabè tradition that helps defuse conflicts through laughter."),
     ],
     quizzes=[
         quiz(("De quoi se moquent les Gourounsi ?", "What do the Gurunsi tease about?"),
              [("Des arachides des Bissa", "The Bissa's groundnuts"), ("De leurs chevaux", "Their horses"), ("De leurs maisons", "Their houses")], 0),
         quiz(("Quelle est la règle de la parenté à plaisanterie ?", "What is the rule of joking kinship?"),
              [("Se taquiner sans se fâcher", "Tease without getting angry"), ("Ne jamais se parler", "Never speak to each other"), ("Se battre", "Fight")], 0),
     ],
     glossary=[gloss("parenté à plaisanterie", "fr", "Alliance entre peuples ou familles qui ont le droit de se moquer les uns des autres, à condition de ne jamais se fâcher.", "An alliance between peoples or families who may mock each other, on condition they never take offence.")],
     source=("La parenté à plaisanterie entre Bissa et Gourounsi, liée aux arachides, est rapportée notamment par Afrik.com. Mise en récit libre et simplifiée.",
             "The joking kinship between Bissa and Gurunsi, linked to groundnuts, is reported notably by Afrik.com. Free, simplified retelling."))

tale(54, "le-pecheur-de-bagre-et-le-poisson-genie", type="conte", region="nakambe", place="Bagré",
     coords=(11.47, -0.55), people="Bissa", language="bissa", duration=4, age=6,
     tags=["pêche", "génies", "avidité", "lac"], cover=1,
     fr=("Le pêcheur de Bagré et le poisson-génie", "Le lac généreux",
         "Sur le lac de Bagré, un pêcheur attrape un poisson qui parle et lui promet des prises abondantes, à une condition : ne jamais pêcher plus que ce dont il a besoin.",
         "Le lac nourrit ceux qui le respectent ; l'avidité vide les filets."),
     en=("The Fisherman of Bagré and the Spirit Fish", "The generous lake",
         "On Lake Bagré, a fisherman catches a talking fish that promises him plentiful catches, on one condition: never fish more than he needs.",
         "The lake feeds those who respect it; greed empties the nets."),
     scenes=[
         scene(art("dawn", "lake", it("sun", 16, 240), it("man", 40, c="#2F3E6B"), it("rope", 50), it("catfish", 62, 6), it("palm", 86, 30)),
               "Sur les rives du grand lac de Bagré vivait Kassoum, un pêcheur bissa. Un matin, il remonta dans son filet un poisson aux écailles dorées, qui lui parla d'une voix douce : « Relâche-moi, et je te ferai riche. »",
               "On the shores of great Lake Bagré lived Kassoum, a Bissa fisherman. One morning he pulled up in his net a fish with golden scales, which spoke to him in a soft voice: \"Let me go, and I will make you rich.\""),
         scene(art("day", "lake", it("sun", 82, 300), it("man-up", 40, c="#2F3E6B"), it("catfish", 58, 6, 1.3), it("catfish", 70, 4)),
               "Kassoum le relâcha. Le génie tint parole : chaque jour, son filet se remplissait. « Mais attention, dit le poisson, ne prends jamais plus que ce dont ta famille a besoin. »",
               "Kassoum let it go. The spirit kept its word: every day his net filled up. \"But beware,\" said the fish, \"never take more than your family needs.\"",
               choice(("Que va faire Kassoum ?", "What will Kassoum do?"),
                      [("Respecter la règle", "Respect the rule"), ("Pêcher toujours plus", "Fish more and more")], 0,
                      ("Au début, Kassoum respecta la règle… puis un marchand arriva.", "At first Kassoum respected the rule… then a trader arrived."))),
         scene(art("dusk", "lake", it("man-point", 30, c="#7C3109"), it("man", 46, c="#2F3E6B"), it("sack", 58), it("catfish", 74, 4)),
               "Le marchand lui proposa de tout acheter. Kassoum jeta ses filets matin et soir, vendit, puis pêcha encore. Mais un jour, son filet revint vide, puis le lendemain, puis le jour suivant.",
               "The trader offered to buy everything. Kassoum cast his nets morning and evening, sold, then fished again. But one day his net came back empty, then the next day, then the day after."),
         scene(art("day", "lake", it("sun", 84, 300), it("man", 40, c="#2F3E6B"), it("child", 54), it("catfish", 70, 6)),
               "Kassoum comprit sa faute et demanda pardon au lac. Il reprit une pêche mesurée, et les poissons revinrent peu à peu. Aujourd'hui, autour de Bagré, on respecte les saisons de pêche pour que le lac nourrisse tout le monde.",
               "Kassoum understood his mistake and asked the lake for forgiveness. He went back to fishing in moderation, and little by little the fish returned. Today, around Bagré, fishing seasons are respected so the lake can feed everyone."),
     ],
     quizzes=[
         quiz(("Quelle était la condition du poisson-génie ?", "What was the spirit fish's condition?"),
              [("Ne pas pêcher plus que nécessaire", "Not to fish more than needed"), ("Ne jamais pêcher", "Never to fish"), ("Pêcher la nuit", "To fish at night")], 0),
         quiz(("Pourquoi les filets sont-ils revenus vides ?", "Why did the nets come back empty?"),
              [("Kassoum avait trop pêché", "Kassoum had fished too much"), ("Il pleuvait", "It was raining"), ("Le filet était troué", "The net had a hole")], 0),
     ],
     glossary=[gloss("lac de Bagré", "fr", "Grand lac de barrage sur le Nakambé, important pour la pêche et l'irrigation.", "A large reservoir on the Nakambé river, important for fishing and irrigation.")],
     source=("Conte du poisson merveilleux et de l'avidité punie, répandu dans de nombreuses cultures. Version écrite pour KIBARE, située au lac de Bagré, avec un message sur la pêche durable.",
             "A tale of the magic fish and punished greed, found in many cultures. Version written for KIBARE, set at Lake Bagré, with a message about sustainable fishing."))

# ------------------------------------------------------------------ Goulmou
tale(55, "le-chacal-et-la-calebasse-de-miel", type="conte", region="goulmou", place="Fada N'Gourma",
     coords=(12.06, 0.36), people="Gourmantché", language="gulmancema", duration=4, age=5,
     tags=["animaux", "miel", "gourmandise", "ruse"], cover=1,
     fr=("Le chacal et la calebasse de miel", "La gourmandise punie",
         "Le chacal vole la calebasse de miel que les abeilles de Fada gardaient pour la saison sèche. Mais le miel colle, et la ruse se retourne contre lui.",
         "Ce qui est pris par la ruse finit par coller aux doigts du voleur."),
     en=("The Jackal and the Calabash of Honey", "Greed punished",
         "The jackal steals the calabash of honey the bees of Fada were keeping for the dry season. But honey is sticky, and the trick turns against him.",
         "What is taken by trickery ends up sticking to the thief's fingers."),
     scenes=[
         scene(art("day", "savanna", it("sun", 82, 300), it("beehive", 50, 70), it("bees", 56, 120), it("giant-calabash", 30), it("karite", 50, 24)),
               "Fada N'Gourma est le pays du miel. Dans un grand karité, les abeilles avaient rempli une calebasse de miel doré pour les mois sans fleurs. Le chacal, caché dans l'herbe, salivait.",
               "Fada N'Gourma is the land of honey. In a great shea tree, the bees had filled a calabash with golden honey for the months without flowers. The jackal, hidden in the grass, was drooling."),
         scene(art("dusk", "savanna", it("dog", 40, c="#C9822B"), it("giant-calabash", 56), it("bees", 70, 140)),
               "Le chacal dit aux abeilles : « Le lièvre vient voler votre miel, allez vite le chasser ! » Les abeilles s'envolèrent. Le chacal plongea la tête dans la calebasse.",
               "The jackal told the bees: \"The hare is coming to steal your honey, go and chase him away!\" The bees flew off. The jackal plunged his head into the calabash.",
               choice(("Que va-t-il arriver au chacal ?", "What will happen to the jackal?"),
                      [("Il va rester coincé", "He'll get stuck"), ("Il va s'enfuir sans problème", "He'll escape with no trouble")], 0,
                      ("Le miel était si épais que la calebasse resta collée à sa tête !", "The honey was so thick that the calabash stuck to his head!"))),
         scene(art("dusk", "savanna", it("dog", 46, c="#C9822B"), it("giant-calabash", 50, 30, 0.6), it("bees", 66, 120), it("hare", 80)),
               "Aveuglé, la tête dans la calebasse, le chacal tourna en rond et se cogna aux arbres. Les abeilles revinrent, furieuses d'avoir été trompées, et le piquèrent de partout.",
               "Blinded, head stuck in the calabash, the jackal ran in circles and bumped into trees. The bees came back, furious at being tricked, and stung him all over."),
         scene(art("day", "village", it("sun", 84, 300), it("dog", 30, c="#C9822B", flip=True), it("beehive", 64, 70), it("woman", 80)),
               "Le chacal s'enfuit, le museau gonflé. Depuis, dit-on à Fada, il rôde la nuit et n'ose plus approcher des ruches. Et les apiculteurs gourmantché répètent : « Le miel se partage, il ne se vole pas. »",
               "The jackal ran off with a swollen snout. Since then, people in Fada say, he prowls at night and no longer dares go near the hives. And Gourmantché beekeepers repeat: \"Honey is shared, not stolen.\""),
     ],
     quizzes=[
         quiz(("Quel mensonge a dit le chacal ?", "What lie did the jackal tell?"),
              [("Que le lièvre venait voler le miel", "That the hare was coming to steal the honey"), ("Qu'il pleuvait", "That it was raining"), ("Qu'il était malade", "That he was ill")], 0),
         quiz(("Pour quoi Fada N'Gourma est-elle connue ?", "What is Fada N'Gourma known for?"),
              [("Son miel", "Its honey"), ("Ses montagnes", "Its mountains"), ("La mer", "The sea")], 0),
     ],
     glossary=[gloss("apiculteur", "fr", "Personne qui élève des abeilles pour récolter le miel.", "A person who keeps bees to collect honey.")],
     source=("Conte d'animaux écrit pour KIBARE dans la tradition des contes de ruse gourmantché ; le miel de Fada N'Gourma est une production réputée de l'Est du Burkina.",
             "An animal tale written for KIBARE in the tradition of Gourmantché trickster tales; Fada N'Gourma honey is a renowned product of eastern Burkina."))

# ------------------------------------------------------------------ Nazinon
tale(56, "la-tortue-au-festin-des-oiseaux", type="conte", region="nazinon", place="Pô",
     coords=(11.17, -1.15), people="Kassena", language="kasem", duration=5, age=5,
     tags=["animaux", "pourquoi", "gourmandise", "ciel"], cover=1,
     fr=("La tortue au festin des oiseaux", "Pourquoi sa carapace est en morceaux",
         "Les oiseaux sont invités à un festin dans le ciel. La tortue, rusée et gourmande, se fait prêter des plumes… et un nouveau nom.",
         "Celui qui trompe ses amis pour tout avoir finit par tomber de haut."),
     en=("The Tortoise at the Birds' Feast", "Why her shell is in pieces",
         "The birds are invited to a feast in the sky. The tortoise, cunning and greedy, borrows feathers… and a new name.",
         "Whoever tricks friends to get everything ends up falling from a great height."),
     scenes=[
         scene(art("day", "savanna", it("sun", 82, 300), it("tortoise", 34, s=1.4), it("bird-small", 54, 40), it("guinea-fowl", 66, s=1.1), it("partridge", 80)),
               "Un jour, le ciel invita tous les oiseaux à un grand festin. La tortue, qui ne savait pas voler, supplia : « Prêtez-moi chacun une plume, et j'irai avec vous. » Les oiseaux, généreux, acceptèrent.",
               "One day the sky invited all the birds to a great feast. The tortoise, who couldn't fly, begged: \"Each of you lend me a feather, and I'll come with you.\" The generous birds agreed."),
         scene(art("day", "savanna", it("tortoise", 46, 150, 1.4), it("bird-small", 30, 160), it("bird-small", 66, 170), it("cloud", 50, 270)),
               "Pendant le vol, la tortue dit : « Au festin, chacun prend un nouveau nom. Moi, je m'appellerai Vous-Tous. » Arrivés au ciel, l'hôte annonça : « Ce repas est pour vous tous ! »",
               "During the flight the tortoise said: \"At the feast, everyone takes a new name. I'll be called All-of-You.\" When they reached the sky, the host announced: \"This meal is for all of you!\"",
               choice(("Qui va manger le repas ?", "Who will eat the meal?"),
                      [("La tortue, grâce à sa ruse", "The tortoise, thanks to her trick"), ("Tous les oiseaux", "All the birds")], 0,
                      ("« C'est moi, Vous-Tous ! » dit la tortue, et elle mangea presque tout.", "\"That's me, All-of-You!\" said the tortoise, and she ate almost everything."))),
         scene(art("dusk", "savanna", it("tortoise", 46, 150, 1.4), it("bird-small", 30, 180), it("bird-small", 70, 190), it("cloud", 40, 270, c="storm")),
               "Furieux, les oiseaux reprirent chacun leur plume. La tortue, sans ailes, demanda au perroquet de dire à sa femme d'étaler des pagnes moelleux devant la case. Mais le perroquet, vexé, dit l'inverse : « Sortez les pierres et les houes ! »",
               "Furious, the birds each took back their feather. The featherless tortoise asked the parrot to tell her wife to spread soft cloths in front of the hut. But the offended parrot said the opposite: \"Bring out the stones and hoes!\""),
         scene(art("day", "village", it("sun", 84, 300), it("tortoise", 46, s=1.4), it("rock", 60), it("painted-house", 80, 30, 0.7), it("woman", 26)),
               "La tortue sauta et s'écrasa sur les pierres : sa carapace se brisa en mille morceaux. Sa femme les recolla patiemment. Voilà pourquoi, au pays kassena comme partout, la carapace de la tortue est faite de petits morceaux.",
               "The tortoise jumped and crashed onto the stones: her shell shattered into a thousand pieces. Her wife patiently glued them back together. That is why, in Kassena country as everywhere, the tortoise's shell is made of little pieces."),
     ],
     quizzes=[
         quiz(("Quel nom la tortue a-t-elle choisi ?", "What name did the tortoise choose?"),
              [("Vous-Tous", "All-of-You"), ("Reine", "Queen"), ("Plume", "Feather")], 0),
         quiz(("Pourquoi la carapace est-elle en morceaux ?", "Why is the shell in pieces?"),
              [("La tortue est tombée du ciel", "The tortoise fell from the sky"), ("Un éléphant l'a écrasée", "An elephant crushed it"), ("Elle est née ainsi", "She was born that way")], 0),
     ],
     glossary=[gloss("carapace", "fr", "Coquille dure qui protège le corps de la tortue.", "The hard shell that protects the tortoise's body.")],
     source=("Conte du « festin dans le ciel », l'un des plus répandus d'Afrique de l'Ouest (Igbo, Yoruba, Mossi, Kassena…). Version écrite pour KIBARE, située en pays kassena, autour de Pô.",
             "The \"feast in the sky\" tale, one of the most widespread in West Africa (Igbo, Yoruba, Mossi, Kassena…). Version written for KIBARE, set in Kassena country around Pô."))
